289	function syncContactHead(progress: number): void {
290	  const section = document.querySelector<HTMLElement>(CONTACT_SECTION_SELECTOR);
291	  const head = document.querySelector<HTMLElement>(CONTACT_HEAD_SELECTOR);
292	  const actions = document.querySelector<HTMLElement>(CONTACT_ACTIONS_SELECTOR);
293	  if (!section || !head || !actions) return;
294	  const textItems = Array.from(
295	    head.querySelectorAll<HTMLElement>(".mask-target"),
296	  );
297	  const actionItems = Array.from(
298	    document.querySelectorAll<HTMLElement>(CONTACT_ACTION_ITEM_SELECTOR),
299	  );
300	  // Keep the contact panel visible through the footer zone and hide it only
301	  // when the scene is left or rewound before the reveal threshold.
302	  const shouldShow = progress >= CONTACT_HEAD_TRANSITION.revealStart;
303	
304	  if (mainSceneDomState.isContactActionsVisible !== shouldShow) {
305	    mainSceneDomState.isContactActionsVisible = shouldShow;
306	    mainSceneDomState.contactActionTimers = clearTimers(
307	      mainSceneDomState.contactActionTimers,
308	    );
309	    const queue = shouldShow ? actionItems : actionItems.slice().reverse();
310	    const delayStep = shouldShow
311	      ? CONTACT_HEAD_TRANSITION.revealStagger
312	      : CONTACT_HEAD_TRANSITION.hideStagger;
313	    queue.forEach((item, index) => {
314	      const timerId = window.setTimeout(
315	        () => {
316	          item.classList.add(INIT_DOM_CLASSES.blockBase);
317	          item.classList.remove(INIT_DOM_CLASSES.boxHidden);
318	          if (shouldShow) {
319	            item.classList.remove("is-block-reveal-down");
320	            BlockReveal.reveal(item);
321	            return;
322	          }
323	          item.classList.remove(INIT_DOM_CLASSES.blockUp);
324	          item.classList.add("is-block-reveal-down");
325	        },
326	        index * delayStep * 1000,
327	      );
328	      mainSceneDomState.contactActionTimers.push(timerId);
329	    });
330	  }
331	
332	  if (mainSceneDomState.isContactHeadVisible === shouldShow) return;
333	  mainSceneDomState.isContactHeadVisible = shouldShow;
334	  mainSceneDomState.contactHeadTimers = clearTimers(
335	    mainSceneDomState.contactHeadTimers,
336	  );
337	
338	  if (shouldShow) {
339	    section.dataset.active = "true";
340	    head.dataset.active = "true";
341	    actions.dataset.active = "true";
342	    TextReveal.setVisibleOff(textItems);
343	    textItems.forEach((item, index) => {
344	      const timerId = window.setTimeout(
345	        () => {
346	          TextReveal.setVisibleOn(item);
347	        },
348	        index * CONTACT_HEAD_TRANSITION.revealStagger * 1000,
349	      );
350	      mainSceneDomState.contactHeadTimers.push(timerId);
351	    });
352	    return;
353	  }
354	
355	  textItems
356	    .slice()
357	    .reverse()
358	    .forEach((item, index) => {
359	      const timerId = window.setTimeout(
360	        () => {
361	          TextReveal.setVisibleOff(item);
362	        },
363	        index * CONTACT_HEAD_TRANSITION.hideStagger * 1000,
364	      );
365	      mainSceneDomState.contactHeadTimers.push(timerId);
366	    });
367	
368	  const hideTimerId = window.setTimeout(
369	    () => {
370	      section.dataset.active = "false";
371	      head.dataset.active = "false";
372	      actions.dataset.active = "false";
373	    },
374	    (Math.max(textItems.length - 1, 0) *
375	      CONTACT_HEAD_TRANSITION.hideStagger +
376	      CONTACT_HEAD_TRANSITION.hideSettleDuration) *
377	      1000,
378	  );
379	  mainSceneDomState.contactHeadTimers.push(hideTimerId);
380	}
