201	
202	      if (
203	        !Number.isFinite(spec.color as number) ||
204	        !Number.isFinite(spec.intensity as number)
205	      ) {
206	        return;
207	      }
208	
209	      const light = createPointLightFromSpec(
210	        spec,
211	        Number(spec.color),
212	        Number(spec.intensity),
213	      );
214	      const position = spec.position ?? {};
215	      light.position.set(position.x ?? 0, position.y ?? 0, position.z ?? 0);
216	      light.name = `ground:${spec.id}`;
217	      obj.add(light);
218	      this._panelLights.push(light);
219	    });
220	  }
